import { OPERATION_ID_LENGTH } from './operation.js';

/**
 * A payment's PUBLIC tracking code — the one code a customer is shown on every invoice,
 * before anything is paid, quotes to support afterwards, and the code every operator log
 * names.
 *
 * ## Round 4 (PR-C): the short code IS the tracking code
 *
 * Since PR-C every payment has an 8-character public code (`payments.code`, see
 * `public-code.ts`), generated by the database at insert and backfilled onto every existing
 * and imported row. It is THE tracking code: `paymentTrackingCode(payment)` returns it, and
 * every surface — the bot, the customer notification lane, the operator's Telegram review,
 * the financial log, the operational events and the Web Admin — calls this one accessor.
 *
 * The FIX-02 code it replaces (below) did not fit the owner's rule and was not kept beside it
 * as a second code: it is sixteen hex characters, it is a hash rather than a unique key, and
 * it exists only for references this installation wrote — an imported payment's reference has
 * another shape, so an imported payment had no short code at all. One payment, one code.
 *
 * ## The FIX-02 code, kept for search only
 *
 * `legacyPaymentTrackingCode` is the operation-id half of the payment's stored `reference`
 * (`<operation id>:<role>`, `PaymentService.referenceFor`). Customers were SHOWN it on every
 * invoice from FIX-02 until PR-C, so the payment search still accepts it
 * (`trackingCodeFromSearch`) — a code a customer already holds must keep finding their
 * payment. It is printed by nothing new, and it is the accessor's fallback only for a row
 * the backfill has not yet reached (never the case once `pnpm db:migrate` has completed).
 * The stored reference, the ledger keys, the idempotency rows and every provider id are
 * untouched by either code.
 */
export const PAYMENT_TRACKING_CODE_PATTERN = new RegExp(`^[0-9a-f]{${OPERATION_ID_LENGTH}}$`);

/** `<operation id>:<role>` — the only shape a payment reference is written in. */
const DERIVED_REFERENCE = new RegExp(`^([0-9a-f]{${OPERATION_ID_LENGTH}}):[a-z][a-z-]*$`);

/**
 * THE payment tracking code accessor. Every surface that shows a payment's code calls this,
 * so there is one answer to "what is this payment's tracking code": the payment's 8-character
 * public code, or — only for a row the backfill has not reached — its FIX-02 code.
 */
export function paymentTrackingCode(payment: {
  readonly code: string | null;
  readonly reference: string;
}): string {
  return payment.code ?? legacyPaymentTrackingCode(payment.reference);
}

/**
 * The FIX-02 code: the operation-id half of a stored reference. Search and the accessor's
 * fallback only. A reference of any other shape is returned unchanged rather than cut
 * somewhere a colon happens to be: a guess that shortened an unknown reference could make
 * two different payments print one code.
 */
export function legacyPaymentTrackingCode(reference: string): string {
  const derived = DERIVED_REFERENCE.exec(reference);
  return derived === null ? reference : (derived[1] as string);
}

/**
 * What a typed search term would be as a FIX-02 tracking code, or null (the 8-character code
 * is `publicCodeFromSearch`). Case and surrounding
 * whitespace are forgiven (a code read aloud or retyped from a screenshot), and a full
 * stored reference pasted from an older screen is reduced to its code, so both find the
 * payment.
 */
export function trackingCodeFromSearch(term: string): string | null {
  const value = term.trim().toLowerCase();
  if (PAYMENT_TRACKING_CODE_PATTERN.test(value)) return value;
  const derived = DERIVED_REFERENCE.exec(value);
  return derived === null ? null : (derived[1] as string);
}

/**
 * The invoice templates that REQUIRE `{reference}` since FIX-02 — every invoice shown before
 * a gateway payment is made. A tenant override of one of them saved before that requirement
 * cannot carry the code, and template bodies are stored raw and never rewritten, so the
 * resolver appends `bot.payment.tracking_code_line` to such an override at render time —
 * for these keys only, and only when the override's body has no `{reference}` of its own.
 */
export const TRACKING_CODE_LINE_KEYS = [
  'bot.payment.gateway_preparing',
  'bot.payment.gateway_invoice',
  'bot.payment.gateway_invoice_order_fee',
  'bot.payment.gateway_invoice_topup_fee',
  'bot.payment.stars_invoice_order',
  'bot.payment.stars_invoice_order_fee',
  'bot.payment.stars_invoice_topup',
  'bot.payment.stars_invoice_topup_fee',
  'bot.payment.gateway_card_invoice',
] as const;

/** The line itself, as a template key, so its words live in the catalogue. */
export const TRACKING_CODE_LINE_KEY = 'bot.payment.tracking_code_line' as const;
